describe('Settlement-discount auto Notes — PURCHASE (Payment -> Debit Note)', () => {
  it('TEST 1: no discount -> no auto note', async () => {
    const bill = await mkPurchase(10000);
    const res = await postPayment({ bill, amount: 10000, discount: 0 });
    assert.equal(res.status, 201, JSON.stringify(res.body));
    const notes = await autoNotesFor(unwrap(res)._id);
    assert.equal(notes.length, 0);
  });

  it('TEST 2: Payment 9,500 + Discount 500 -> exactly one Purchase Debit Note', async () => {
    const bill = await mkPurchase(10000);
    const res = await postPayment({ bill, amount: 9500, discount: 500 });
    assert.equal(res.status, 201, JSON.stringify(res.body));
    const voucher = unwrap(res);

    const notes = await autoNotesFor(voucher._id);
    assert.equal(notes.length, 1);
    const note = notes[0];
    assert.equal(note.noteType, 'Debit');
    assert.equal(note.noteSide, 'Purchase');
    assert.equal(note.autoGenerated, true);
    assert.equal(String(note.sourceVoucherId), String(voucher._id));
    assert.equal(Number(note.amount), 500);
    assert.equal(String(note.accountingEntryId), String(voucher.accountingEntryId));

    const billAfter = await Purchase.findById(bill._id);
    assert.equal(Number(billAfter.paidAmount), 10000);
    assert.equal(Number(billAfter.netAmount) - Number(billAfter.paidAmount), 0);

    const { dr, cr, entry } = await drCr(voucher.accountingEntryId);
    assert.ok(Math.abs(dr - cr) < 0.01, `payment journal unbalanced Dr=${dr} Cr=${cr}`);
    assert.ok(Math.abs(dr - 10000) < 0.01);
    const discountLines = entry.lines.filter(l => l.ledgerName === 'Discount Received');
    assert.equal(discountLines.length, 1);
    assert.equal(Number(discountLines[0].amount), 500);

    const noteOwnEntries = await AccountingEntry.find({ companyId, refId: note._id });
    assert.equal(noteOwnEntries.length, 0);
  });

  it('TEST 3: retrying create makes no second note', async () => {
    const bill = await mkPurchase(3000);
    const created = await postPayment({ bill, amount: 2700, discount: 300 });
    assert.equal(created.status, 201);
    const notesFirst = await autoNotesFor(unwrap(created)._id);
    assert.equal(notesFirst.length, 1);
  });

  it('TEST 4: editing discount 500 -> 300 replaces the Debit Note, no stale/duplicate', async () => {
    const bill = await mkPurchase(10000);
    const created = await postPayment({ bill, amount: 9500, discount: 500 });
    const voucher = unwrap(created);
    const [oldNote] = await autoNotesFor(voucher._id);

    const editRes = await request(app).put(`/api/accounting/payments/${voucher._id}`).set(auth(tok)).send({
      partyLedgerId: supplierLedgerId, bankLedgerId, paymentMode: 'NEFT', bookKind: 'bank',
      accBill: 'B', status: 'Posted', amount: 9700, date: new Date('2026-07-05').toISOString(),
      narration: 'discount reduced',
      againstInvoices: [{ invoiceId: bill._id, invoiceNo: bill.invoiceNo, amount: 9700, discount: 300 }],
    });
    assert.equal(editRes.status, 200, JSON.stringify(editRes.body));

    const allNotes = await DebitCreditNote.find({ companyId, sourceVoucherId: voucher._id, autoGenerated: true });
    const active = allNotes.filter(n => n.status === 'Posted');
    assert.equal(active.length, 1);
    assert.equal(Number(active[0].amount), 300);
    const oldAfter = allNotes.find(n => String(n._id) === String(oldNote._id));
    assert.equal(oldAfter.status, 'Reversed');

    const billAfter = await Purchase.findById(bill._id);
    assert.equal(Number(billAfter.paidAmount), 10000);
  });

  it('TEST 5: reversing the Payment retires its Debit Note and restores outstanding', async () => {
    const bill = await mkPurchase(10000);
    const created = await postPayment({ bill, amount: 9500, discount: 500 });
    const voucher = unwrap(created);
    const [note] = await autoNotesFor(voucher._id);

    const revRes = await request(app).post(`/api/accounting/payments/${voucher._id}/reverse`).set(auth(tok))
      .send({ reason: 'test reversal' });
    assert.equal(revRes.status, 200, JSON.stringify(revRes.body));

    const noteAfter = await DebitCreditNote.findById(note._id);
    assert.equal(noteAfter.status, 'Reversed');

    const billAfter = await Purchase.findById(bill._id);
    assert.equal(Number(billAfter.paidAmount), 0);
  });

  it('TEST 6: manual Edit/Reverse of an auto Debit Note is safely rejected', async () => {
    const bill = await mkPurchase(10000);
    const created = await postPayment({ bill, amount: 9500, discount: 500 });
    const voucher = unwrap(created);
    const [note] = await autoNotesFor(voucher._id);

    const editRes = await request(app).put(`/api/notes/${note._id}`).set(auth(tok)).send({ amount: 999 });
    assert.equal(editRes.status, 400);
    assert.match(editRes.body.message, /automatically generated/i);

    const revRes = await request(app).post(`/api/notes/${note._id}/reverse`).set(auth(tok)).send({});
    assert.equal(revRes.status, 400);
    assert.match(revRes.body.message, /automatically generated/i);
  });
});

