describe('Settlement-discount auto Notes — multiple bills in one voucher', () => {
  it('two bills settled with different discounts each get their own correct note', async () => {
    const billA = await mkSale(5000);
    const billB = await mkSale(7000);
    // Adjust 4800 + discount 200 on A, Adjust 6500 + discount 500 on B = cash 11300
    const res = await request(app).post('/api/accounting/receipts').set(auth(tok)).send({
      partyLedgerId: customerLedgerId, bankLedgerId, paymentMode: 'NEFT', bookKind: 'bank',
      accBill: 'B', status: 'Posted', amount: 11300, date: new Date('2026-07-08').toISOString(),
      narration: 'multi-bill receipt',
      againstInvoices: [
        { invoiceId: billA._id, invoiceNo: billA.invoiceNo, amount: 4800, discount: 200 },
        { invoiceId: billB._id, invoiceNo: billB.invoiceNo, amount: 6500, discount: 500 },
      ],
    });
    assert.equal(res.status, 201, JSON.stringify(res.body));
    const voucher = unwrap(res);

    const notes = await autoNotesFor(voucher._id);
    assert.equal(notes.length, 2, 'one note per discounted bill, no duplicate bill adjustment');
    const noteA = notes.find(n => String(n.againstInvoiceId) === String(billA._id));
    const noteB = notes.find(n => String(n.againstInvoiceId) === String(billB._id));
    assert.equal(Number(noteA.amount), 200);
    assert.equal(Number(noteB.amount), 500);

    const aAfter = await Sales.findById(billA._id);
    const bAfter = await Sales.findById(billB._id);
    assert.equal(Number(aAfter.paidAmount), 5000, 'Bill A fully settled (4800 cash + 200 discount)');
    assert.equal(Number(bAfter.paidAmount), 7000, 'Bill B fully settled (6500 cash + 500 discount)');

    const { dr, cr, entry } = await drCr(voucher.accountingEntryId);
    assert.ok(Math.abs(dr - cr) < 0.01);
    const discountLines = entry.lines.filter(l => l.ledgerName === 'Discount Allowed');
    assert.equal(discountLines.length, 1, 'both discounts sum into ONE Discount Allowed leg on the voucher journal');
    assert.equal(Number(discountLines[0].amount), 700, '200 + 500 combined');
  });
});

/* ══════════════════════════════════════════════════════════════════════ */
describe('Regression — manual Notes and plain vouchers are unaffected', () => {
  it('a manually-created Sales Credit Note (not linked to any voucher) still posts its own journal, and can still be edited and reversed', async () => {
    const bill = await mkSale(2000);
    const createRes = await request(app).post('/api/notes').set(auth(tok)).send({
      noteType: 'Credit', noteSide: 'Sales', partyLedgerId: customerLedgerId,
      date: new Date('2026-07-09').toISOString(), amount: 200, amountMode: 'Inclusive',
      gstRate: 0, againstInvoiceId: bill._id, reason: 'Manual goods return',
      status: 'Posted',
    });
    assert.equal(createRes.status, 201, JSON.stringify(createRes.body));
    const note = unwrap(createRes);
    assert.equal(note.autoGenerated, false, 'manual note defaults to non-auto');
    assert.ok(note.accountingEntryId, 'manual note posts its own journal');

    const ownEntries = await AccountingEntry.find({ companyId, refId: note._id });
    assert.equal(ownEntries.length, 1, 'manual note owns exactly one independent journal entry');

    const editRes = await request(app).put(`/api/notes/${note._id}`).set(auth(tok)).send({
      noteType: 'Credit', partyLedgerId: customerLedgerId, date: new Date('2026-07-09').toISOString(),
      amount: 250, amountMode: 'Inclusive', gstRate: 0, againstInvoiceId: bill._id,
      reason: 'Manual goods return (revised)', status: 'Posted',
    });
    assert.equal(editRes.status, 200, JSON.stringify(editRes.body));
    assert.equal(Number(unwrap(editRes).amount), 250);

    const reverseRes = await request(app).post(`/api/notes/${note._id}/reverse`).set(auth(tok))
      .send({ reason: 'test cleanup' });
    assert.equal(reverseRes.status, 200, JSON.stringify(reverseRes.body));
    const noteAfter = await DebitCreditNote.findById(note._id);
    assert.equal(noteAfter.status, 'Reversed');
  });

  it('a plain Receipt/Payment with no discount still posts correctly (no notes, balanced journal)', async () => {
    const bill = await mkSale(1500);
    const res = await postReceipt({ bill, amount: 1500, discount: 0 });
    assert.equal(res.status, 201);
    const voucher = unwrap(res);
    const notes = await autoNotesFor(voucher._id);
    assert.equal(notes.length, 0);
    const { dr, cr } = await drCr(voucher.accountingEntryId);
    assert.ok(Math.abs(dr - cr) < 0.01);
    assert.ok(Math.abs(dr - 1500) < 0.01);
  });
});
